    public EventCallback<Product> OnAddToCart { get; set; }
}

@namespace sv_69866c81795546949c3f0446bfde9678.Components.Catalog

<aside class="catalog-filters">
    <h3>Filters</h3>

    <div class="filter-section">
        <h4>Categories</h4>
        @foreach (var category in Categories)
        {
            <label class="filter-checkbox">
                <input type="checkbox"
                       checked="@IsSelected(category)"
                       @onchange="@(e => ToggleCategory(category, (bool)e.Value!))" />
                @category
            </label>
        }
    </div>

    <div class="filter-section">
        <h4>Price Range</h4>
        <label>
            Min:
            <input type="number" min="0" step="0.01"
                   value="@minPrice"
                   @onchange="@(e => minPrice = ParseDecimal(e.Value))" />
        </label>
        <label>
            Max:
            <input type="number" min="0" step="0.01"
                   value="@maxPrice"
                   @onchange="@(e => maxPrice = ParseDecimal(e.Value))" />
        </label>
    </div>

    <div class="filter-section">
        <label class="filter-checkbox">
            <input type="checkbox"
                   checked="@inStockOnly"
                   @onchange="@(e => inStockOnly = (bool)e.Value!)" />
            In Stock Only
        </label>
    </div>

    <div class="filter-actions">
        <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
    </div>
</aside>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = [];

    [Parameter]
    public EventCallback<ProductFilter> OnApply { get; set; }

    [Parameter]
    public EventCallback OnClear { get; set; }

    private List<string> selectedCategories = [];
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;

    private bool IsSelected(string category) => selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool selected)
    {
        if (selected)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: selectedCategories.Count > 0 ? new List<string>(selectedCategories) : null,
            MinPrice: minPrice,
            MaxPrice: maxPrice,
            InStockOnly: inStockOnly
        );
        await OnApply.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        selectedCategories = [];
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        await OnClear.InvokeAsync();
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}

@namespace sv_69866c81795546949c3f0446bfde9678.Components.Catalog

<div class="catalog-toolbar">
    <div class="toolbar-sort">
        <label for="sort-select">Sort by:</label>
        <select id="sort-select" value="@SortBy" @onchange="HandleSortChange">
            <option value="price_asc">Price: Low to High</option>
            <option value="price_desc">Price: High to Low</option>
            <option value="name_asc">Name: A-Z</option>
            <option value="rating_desc">Rating: Highest</option>
        </select>
    </div>
    <div class="toolbar-info">
        @if (TotalCount > 0)
        {
            var start = (Page - 1) * PageSize + 1;
            var end = Math.Min(Page * PageSize, TotalCount);
            <span>Showing @start–@end of @TotalCount products</span>
        }
    </div>
</div>

@code {
    [Parameter] public string SortBy { get; set; } = "price_asc";
    [Parameter] public int Page { get; set; }
    [Parameter] public int PageSize { get; set; }
    [Parameter] public int TotalCount { get; set; }

    [Parameter] public EventCallback<string> OnSortChanged { get; set; }

    private async Task HandleSortChange(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}

@namespace sv_69866c81795546949c3f0446bfde9678.Components.Catalog

<nav class="catalog-pagination" aria-label="Product pagination">
    <button class="btn-page" disabled="@(CurrentPage <= 1)" @onclick="@(() => GoToPage(CurrentPage - 1))">
        Previous
    </button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var page = i;
        <button class="btn-page @(page == CurrentPage ? "active" : "")"
                @onclick="@(() => GoToPage(page))">
            @page
        </button>
    }

    <button class="btn-page" disabled="@(CurrentPage >= TotalPages)" @onclick="@(() => GoToPage(CurrentPage + 1))">
        Next
    </button>
</nav>

@code {
    [Parameter] public int CurrentPage { get; set; }
    [Parameter] public int TotalPages { get; set; }
    [Parameter] public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}

@page "/catalog"
@using sv_69866c81795546949c3f0446bfde9678.Components.Catalog
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-layout">
    <CatalogFilters Categories="categories"
                    OnApply="HandleApplyFilters"
                    OnClear="HandleClearFilters" />

    <main class="catalog-main">
        @if (isLoading)
        {
            <div class="catalog-loading">Loading products...</div>
        }
        else if (errorMessage is not null)
        {
            <div class="catalog-error">
                <p>@errorMessage</p>
                <button @onclick="LoadProducts">Retry</button>
            </div>
        }
        else if (result is not null && result.Items.Count == 0)
        {
            <div class="catalog-empty">
                <p>No products found matching your criteria.</p>
            </div>
        }
        else if (result is not null)
        {
            <CatalogToolbar SortBy="@sortBy"
                            Page="result.Page"
                            PageSize="result.PageSize"
                            TotalCount="result.TotalCount"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="result.Items"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            @{
                var totalPages = (int)Math.Ceiling((double)result.TotalCount / result.PageSize);
            }
            @if (totalPages > 1)
            {
                <CatalogPagination CurrentPage="result.Page"
                                   TotalPages="totalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
        }
    </main>
</div>

@code {
    private List<string> categories = [];
    private PagedResult<Product>? result;
    private ProductFilter currentFilter = new(null, null, null, false);
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private int pageSize = 12;
    private bool isLoading;
    private string? errorMessage;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadCategories();
        await LoadProducts();
    }

    private async Task LoadCategories()
    {
        try
        {
            categories = await ProductService.GetCategoriesAsync();
        }
        catch
        {
            categories = [];
        }
    }

    private async Task LoadProducts()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            result = await ProductService.SearchAsync(currentFilter, sortBy, currentPage, pageSize);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products: {ex.Message}";
            result = null;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task HandleApplyFilters(ProductFilter filter)
    {
        currentFilter = filter;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleClearFilters()
    {
        currentFilter = new ProductFilter(null, null, null, false);
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string newSort)
    {
        sortBy = newSort;
        currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        currentPage = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

::deep .catalog-filters {
    width: 25%;
    min-width: 220px;
    padding: 1rem;
    border-right: 1px solid #e0e0e0;
}

.catalog-main {
    width: 75%;
    flex: 1;
}

.catalog-loading,
.catalog-empty,
.catalog-error {
    padding: 2rem;
    text-align: center;
    color: #666;
}

.catalog-error {
    color: #c00;
}

::deep .catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 0;
    border-bottom: 1px solid #e0e0e0;
    margin-bottom: 1rem;
}

::deep .product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

::deep .product-card {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
}

::deep .product-card:hover {
    box-shadow: 0 2px 8px rgba(0,0,0,0.12);
}

::deep .product-image {
    background: #f0f0f0;
    height: 160px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 0.9rem;
}

::deep .product-info {
    padding: 0.75rem;
}

::deep .product-name {
    margin: 0 0 0.25rem;
    font-size: 1rem;
}

::deep .product-price {
    font-weight: bold;
    color: #2a7a2a;
    margin: 0.25rem 0;
}

::deep .product-rating {
    color: #f5a623;
    margin: 0.25rem 0;
}

::deep .badge-out-of-stock {
    display: inline-block;
    background: #f44;
    color: white;
    font-size: 0.75rem;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    margin: 0.25rem 0;
}

::deep .btn-add-to-cart {
    display: block;
    width: 100%;
    margin-top: 0.5rem;
    padding: 0.5rem;
    background: #0066cc;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-add-to-cart:disabled {
    background: #ccc;
    cursor: not-allowed;
}

::deep .filter-section {
    margin-bottom: 1rem;
}

::deep .filter-section h4 {
    margin: 0 0 0.5rem;
}

::deep .filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.3rem;
    cursor: pointer;
}

::deep .filter-section input[type="number"] {
    width: 100%;
    padding: 0.3rem;
    margin-top: 0.25rem;
    box-sizing: border-box;
}

::deep .filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 1rem;
}

::deep .btn-apply {
    padding: 0.5rem;
    background: #0066cc;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-clear {
    padding: 0.5rem;
    background: #eee;
    border: 1px solid #ccc;
    border-radius: 4px;
    cursor: pointer;
}

::deep .catalog-pagination {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 0.3rem;
    margin-top: 1.5rem;
    padding: 1rem 0;
}

::deep .btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #ccc;
    background: white;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-page.active {
    background: #0066cc;
    color: white;
    border-color: #0066cc;
}

::deep .btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

