toolArgs.file_text:
.catalog-layout {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

::deep .catalog-filters {
    width: 25%;
    min-width: 220px;
    padding: 1rem;
    border-right: 1px solid #e0e0e0;
}

.catalog-main {
    width: 75%;
    flex: 1;
}

.catalog-loading,
.catalog-empty,
.catalog-error {
    padding: 2rem;
    text-align: center;
    color: #666;
}

.catalog-error {
    color: #c00;
}

::deep .catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 0;
    border-bottom: 1px solid #e0e0e0;
    margin-bottom: 1rem;
}

::deep .product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

::deep .product-card {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
}

::deep .product-card:hover {
    box-shadow: 0 2px 8px rgba(0,0,0,0.12);
}

::deep .product-image {
    background: #f0f0f0;
    height: 160px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 0.9rem;
}

::deep .product-info {
    padding: 0.75rem;
}

::deep .product-name {
    margin: 0 0 0.25rem;
    font-size: 1rem;
}

::deep .product-price {
    font-weight: bold;
    color: #2a7a2a;
    margin: 0.25rem 0;
}

::deep .product-rating {
    color: #f5a623;
    margin: 0.25rem 0;
}

::deep .badge-out-of-stock {
    display: inline-block;
    background: #f44;
    color: white;
    font-size: 0.75rem;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    margin: 0.25rem 0;
}

::deep .btn-add-to-cart {
    display: block;
    width: 100%;
    margin-top: 0.5rem;
    padding: 0.5rem;
    background: #0066cc;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-add-to-cart:disabled {
    background: #ccc;
    cursor: not-allowed;
}

::deep .filter-section {
    margin-bottom: 1rem;
}

::deep .filter-section h4 {
    margin: 0 0 0.5rem;
}

::deep .filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.3rem;
    cursor: pointer;
}

::deep .filter-section input[type="number"] {
    width: 100%;
    padding: 0.3rem;
    margin-top: 0.25rem;
    box-sizing: border-box;
}

::deep .filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: 1rem;
}

::deep .btn-apply {
    padding: 0.5rem;
    background: #0066cc;
    color: white;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-clear {
    padding: 0.5rem;
    background: #eee;
    border: 1px solid #ccc;
    border-radius: 4px;
    cursor: pointer;
}

::deep .catalog-pagination {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 0.3rem;
    margin-top: 1.5rem;
    padding: 1rem 0;
}

::deep .btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #ccc;
    background: white;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-page.active {
    background: #0066cc;
    color: white;
    border-color: #0066cc;
}

::deep .btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

